from prepare_v5 import *
from identity_scope_v5 import *
def run():
 real=load_context(TOP/'contexts/training_actual');tests=[]
 # Preserve original v4 response and apply new scope gate; no retrospective score change.
 for name,k in [('transaction_sum',2),('supported_conjunction',5)]:
  old=read(V4/'training/responses/feature_adapter'/('eval_real_'+str(k)+'.json'));cat,task,cs=real_task(real,k,'controlled_request');req=real_request(k,cs);a=scope_check(old['prediction'],req);assert not a['passed'];fixed=scope_check({'candidates':cs,'stop_reason':'narrow correction'},req);assert fixed['passed'];tests.append({'case':name,'old_response':pin(V4/'training/responses/feature_adapter'/('eval_real_'+str(k)+'.json')),'old_failure_reproduced':a,'correct_answer_passes':fixed,'old_source_output_retained':True})
 old=read(V4/'training/responses/feature_adapter/eval_syn_4.json');tab=old['prediction']['candidates'][0]['plan']['grain']['table'];child=tab.replace('parent_','child_');rel=old['prediction']['candidates'][0]['plan']['expression']['relationship_id'];req={'kind':'specified','grain_table':child,'relationship':rel,'required_operations':['parent_match_count'],'supported':True};a=scope_check(old['prediction'],req);assert not a['passed'];tests.append({'case':'child_parent_match_replaced_by_parent_child_count','failure':a,'old_response':pin(V4/'training/responses/feature_adapter/eval_syn_4.json')})
 # Missing STATUS filter and vague zero reasons repro from old teachers.
 oldrows=[json.loads(s)for s in (V4/'data_r04/train.jsonl').read_text().splitlines()]
 for name in ['train_actual_12','train_actual_13']:
  r=next(z for z in oldrows if z['id']==name);req={'kind':'specified','supported':True,'population_filters':[{'table':T,'column':'STATUS','value':'S'}]};a=scope_check(r['target'],req);assert not a['passed'];tests.append({'case':name,'failure':a,'input_sha':digest(r['input']),'answer_sha':digest(r['target'])})
 for name,terms in [('train_actual_6',['PROCESS_TIME','unit']),('train_actual_7',['abs']),('train_actual_14',['PROCESS_TIME','unit']),('train_actual_15',['abs'])]:
  r=next(z for z in oldrows if z['id']==name);a=scope_check(r['target'],{'kind':'specified','supported':False,'zero_reason_terms':terms});assert not a['passed'];tests.append({'case':name,'failure':a})
 _,_,cs=real_task(real,5,'same_alias');o={'candidates':cs,'stop_reason':'narrow supported conjunction'};a=bind_candidates(real,o,'call1');b=bind_candidates(real,o,'call2');assert a['candidates'][0]['identity_mapping']['registry_id']!=b['candidates'][0]['identity_mapping']['registry_id'];assert a['candidates'][0]['candidate']==cs[0]
 _,_,other=real_task(real,0,'same_alias');d=bind_candidates(real,{'candidates':other,'stop_reason':'different definition'},'call1');assert a['candidates'][0]['identity_mapping']['registry_id']!=d['candidates'][0]['identity_mapping']['registry_id'];mp=a['candidates'][0]['identity_mapping'];assert not evidence_ref_compatible(mp,'changed_definition',mp['source_version']);assert not evidence_ref_compatible(mp,mp['definition_sha256'],'changed_source')
 # Timestamp parser failure is a measurement limitation, not missing physical ms contract.
 c,a,b,r,n=fixture('cpu_parse_unit_contrast',611);delta={'op':'datetime_diff','args':[col(a,n['end']),col(a,n['start'])],'unit':'ms'};s=candidate(c,'parse_test',delta,a,'Signed timestamp coordinates; parsing and timezone compatibility affect availability.');ch=evaluate_candidates(c,{'candidates':[s],'stop_reason':'narrow'});assert ch['candidates'][0]['measurement_completed'];wrong=deepcopy(s);wrong['expected_unit']='s';bad=evaluate_candidates(c,{'candidates':[wrong],'stop_reason':'narrow'});assert not bad['candidates'][0]['definition_valid']
 write(TOP/'review/CPU_development_regression.json',{'passed':True,'cases':tests,'Boolean_missingness_conjunction_supported':True,'identity_collisions_do_not_overwrite':True,'raw_alias_preserved':True,'changed_definition_source_refs_rejected':True,'valid_datetime_difference_can_have_unavailable_parse_values':True,'expected_unit_mismatch_definition_rejected':bad['candidates'][0]['errors'],'synthetic_datetime_summary':ch['candidates'][0]['feature']['measurement']['summary']})
if __name__=='__main__':run()
